      const stats = [['PACE', paceTxt(d)], ['W-P-S', wps(d)], ['CONS', d.cons != null ? Math.round(d.cons) + '%' : '-']]; const sw = (cw - 32) / 3;
      stats.forEach((s, k) => { b += tx(x + 16 + k * sw + sw / 2, cy + 292, s[1], { s: 15, w: 800, a: 'middle' }) + tx(x + 16 + k * sw + sw / 2, cy + 308, s[0], { s: 9.5, w: 800, c: FAINT, a: 'middle', ls: 1 }); });
