      let cx = x1; const c1 = chip(cx, y + 60, d.label, i === 0 ? GOLD : TEAL, { s: 10.5 }); b += c1.svg; cx += c1.w + 8; const c2 = tierChip(cx, y + 60, d, 10.5); b += c2.svg;
