  /* ============================================================
     6. EXPORT
     ============================================================ */
  function toCanvas(svgStr, scale) {
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(new Blob([svgStr], { type: 'image/svg+xml;charset=utf-8' })); const img = new Image();
      img.onload = () => { const c = document.createElement('canvas'); c.width = Math.round(W * scale); c.height = Math.round(H * scale); const g = c.getContext('2d'); g.drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(url); resolve(c); };
      img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Could not draw the page in this browser')); };
      img.src = url;
    });
  }
  const download = (href, name) => { const a = document.createElement('a'); a.href = href; a.download = name; document.body.appendChild(a); a.click(); a.remove(); };
  const slug = (s) => String(s || 'field-report').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) || 'field-report';
  async function savePng(page, title) { const c = await toCanvas(page.svg, 1.5); download(c.toDataURL('image/png'), 'ifwl-field-report-' + slug(title) + '-' + page.name + '.png'); }
  function pdfMulti(pages) {
    const enc = new TextEncoder(); const parts = []; let len = 0; const offs = [];
    const push = (x) => { const b = typeof x === 'string' ? enc.encode(x) : x; parts.push(b); len += b.length; };
    const obj = (n, body) => { offs[n] = len; push(n + ' 0 obj\n' + body + '\nendobj\n'); };
    const pw = 842, ph = 842 * H / W; const N = pages.length; push('%PDF-1.4\n');
    obj(1, '<< /Type /Catalog /Pages 2 0 R >>');
    obj(2, '<< /Type /Pages /Kids [' + pages.map((_, i) => (3 + i * 3) + ' 0 R').join(' ') + '] /Count ' + N + ' >>');
    pages.forEach((p, i) => {
      const a = 3 + i * 3, c = a + 1, im = a + 2;
      obj(a, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + pw + ' ' + ph.toFixed(2) + '] /Resources << /XObject << /Im0 ' + im + ' 0 R >> >> /Contents ' + c + ' 0 R >>');
      const content = 'q ' + pw + ' 0 0 ' + ph.toFixed(2) + ' 0 0 cm /Im0 Do Q'; obj(c, '<< /Length ' + content.length + ' >>\nstream\n' + content + '\nendstream');
      offs[im] = len; push(im + ' 0 obj\n<< /Type /XObject /Subtype /Image /Width ' + p.iw + ' /Height ' + p.ih + ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' + p.bytes.length + ' >>\nstream\n'); push(p.bytes); push('\nendstream\nendobj\n');
    });
    const total = 3 + N * 3; const xref = len; let x = 'xref\n0 ' + total + '\n0000000000 65535 f \n'; for (let i = 1; i < total; i++) x += String(offs[i]).padStart(10, '0') + ' 00000 n \n';
    push(x + 'trailer\n<< /Size ' + total + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF');
    const out = new Uint8Array(len); let p = 0; parts.forEach((b) => { out.set(b, p); p += b.length; }); return new Blob([out], { type: 'application/pdf' });
  }
  async function savePdf(pages, title, onProg) {
    const jp = []; for (let i = 0; i < pages.length; i++) {
      if (onProg) onProg('Drawing page ' + (i + 1) + ' of ' + pages.length + '…');
      const c = await toCanvas(pages[i].svg, 1.5); const bin = atob(c.toDataURL('image/jpeg', 0.92).split(',')[1]); const bytes = new Uint8Array(bin.length); for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k); jp.push({ bytes, iw: c.width, ih: c.height });
    }
    const u = URL.createObjectURL(pdfMulti(jp)); download(u, 'ifwl-field-report-' + slug(title) + '.pdf'); setTimeout(() => URL.revokeObjectURL(u), 5000);
  }
  function csvOf(m) {
    const q = (v) => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"';
    const head = ['Car', 'Driver', 'Steam ID', 'SimGrid username', 'Category', 'Car model', 'Team', 'Platform', 'IFWL match', 'Licence no.', 'IFWL tier', 'IFWL rating', 'Pace gap %', 'Consistency %', 'Race risk %', 'Sessions', 'Season starts', 'Wins', 'Podiums', 'Avg finish', 'Watch score', 'Watch label', 'Pronunciation'];
    const rows = m.drivers.slice().sort(numSort).map((d) => [d.num, d.display || d.name, d.steamId, d.username, d.cls, d.carName, d.team2, d.platform, d.lic ? (d.accepted ? d.how : 'unconfirmed') : 'none', d.lic && d.accepted ? d.lic.licenceNumber : '', d.tierName, d.rating == null ? '' : Math.round(d.rating), d.pace == null ? '' : r2(d.pace), d.cons == null ? '' : Math.round(d.cons), d.risk == null ? '' : Math.round(d.risk), d.sessions, d.starts, d.season ? d.season.wins : '', d.season ? d.season.pods : '', d.season && d.season.avg != null ? r1(d.season.avg) : '', d.score == null ? '' : d.score, d.label, d.pron]);
    return '﻿' + [head].concat(rows).map((r) => r.map(q).join(',')).join('\r\n');
  }
  async function toDataUrl(url) { try { const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 5000); const r = await fetch(url, { mode: 'cors', signal: ctl.signal }); clearTimeout(t); if (!r.ok) return ''; const b = await r.blob(); if (b.size > 2.5e6) return ''; return await new Promise((res) => { const fr = new FileReader(); fr.onload = () => res(String(fr.result)); fr.onerror = () => res(''); fr.readAsDataURL(b); }); } catch (_) { return ''; } }

